using System;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Threading.Tasks;using System.Windows.Forms;
[assembly:AssemblyVersion("0.14.0.1")]
[assembly:AssemblyFileVersion("0.14.0.1")]
[assembly:AssemblyTitle("Crimson Skies Selective Unified Setup")]
namespace CrimsonSkiesUnified {
 sealed class SetupForm:Form {
  readonly TextBox root=new TextBox{Dock=DockStyle.Fill};readonly TextBox output=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false};
  readonly CheckBox korean=new CheckBox{Text="한글화 / Korean text & fonts",AutoSize=true,Checked=true};readonly CheckBox wide=new CheckBox{Text="와이드스크린·고해상도 / Widescreen & high resolutions",AutoSize=true,Checked=true};readonly CheckBox dub=new CheckBox{Text="한국어 더빙 / Korean voices",AutoSize=true,Checked=true};
  readonly ComboBox captions=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Fill};readonly Label description=new Label{Dock=DockStyle.Fill};readonly Button browse=new Button{Text="폴더 선택 / Browse",AutoSize=true};readonly Button check=new Button{Text="상태 검사 / Check",AutoSize=true};readonly Button apply=new Button{Text="선택 항목 설치 / Install selected",AutoSize=true};readonly Button restore=new Button{Text="설치 전 복구 / Restore",AutoSize=true};readonly Button recover=new Button{Text="중단 작업 복구 / Recover",AutoSize=true};readonly Button play=new Button{Text="플레이 창 열기 / Open game",AutoSize=true};bool busy,changing;
  public SetupForm(string initial){Text="Crimson Skies 통합 설치기 / Unified Setup — 0.14.0 Alpha 1";Font=new Font("맑은 고딕",10);Width=1000;Height=790;MinimumSize=new Size(900,710);StartPosition=FormStartPosition.CenterScreen;AutoScaleMode=AutoScaleMode.Dpi;
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=7,Padding=new Padding(16)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,55));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,36));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,195));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,75));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,80));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,45));
   layout.Controls.Add(new Label{Dock=DockStyle.Fill,Text="원본 게임에서 필요한 기능을 한 번에 설치하세요. / Choose components for your owned game.\r\n지원 빌드 / Build: Windows x64 2608.3123.1.0 · 설치 전 게임과 플레이 창을 종료하세요."},0,0);
   var path=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};path.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));path.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));path.Controls.Add(root,0,0);path.Controls.Add(browse,1,0);layout.Controls.Add(path,0,1);root.AccessibleName="게임 폴더 / Game folder";root.Text=initial??@"C:\XboxGames\Crimson Skies- High Road to Revenge\Content";
   korean.UseMnemonic=wide.UseMnemonic=dub.UseMnemonic=false;
   var group=new GroupBox{Dock=DockStyle.Fill,Text="설치할 기능 / Components"};var options=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5,Padding=new Padding(10)};options.RowStyles.Add(new RowStyle(SizeType.Absolute,30));options.RowStyles.Add(new RowStyle(SizeType.Absolute,30));options.RowStyles.Add(new RowStyle(SizeType.Absolute,30));options.RowStyles.Add(new RowStyle(SizeType.Absolute,25));options.RowStyles.Add(new RowStyle(SizeType.Absolute,33));options.Controls.Add(korean,0,0);options.Controls.Add(wide,0,1);options.Controls.Add(dub,0,2);options.Controls.Add(new Label{Text="한글 자막 / Korean captions",Dock=DockStyle.Fill},0,3);captions.Items.AddRange(new object[]{"원문 번역 자막 / Original translation","더빙 대사 자막 / Match Korean dub","기본 영상 자막만 · 추가 무전 자막 끔 / Movies only"});captions.SelectedIndex=1;captions.AccessibleName="한글 자막 / Korean captions";options.Controls.Add(captions,0,4);group.Controls.Add(options);layout.Controls.Add(group,0,2);layout.Controls.Add(description,0,3);
   var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true};foreach(var b in new[]{check,apply,restore,recover,play}){b.Height=34;buttons.Controls.Add(b);}layout.Controls.Add(buttons,0,4);layout.Controls.Add(output,0,5);layout.Controls.Add(new Label{Dock=DockStyle.Fill,Text="더빙·한글 자막은 한국어 기반을 사용합니다. 와이드스크린은 단독 설치할 수 있습니다.\r\n백업은 로컬 앱 데이터에 보관합니다. 저장 프로필은 변경하지 않습니다. / Saves are not modified."},0,6);Controls.Add(layout);
   browse.Click+=delegate{using(var d=new FolderBrowserDialog{Description="게임 폴더 또는 Content / Game folder or Content",ShowNewFolderButton=false}){if(Directory.Exists(root.Text))d.SelectedPath=root.Text;if(d.ShowDialog(this)==DialogResult.OK)root.Text=d.SelectedPath;}};
   korean.CheckedChanged+=delegate{if(changing)return;changing=true;if(!korean.Checked){dub.Checked=false;captions.SelectedIndex=2;}changing=false;Describe();};
   dub.CheckedChanged+=delegate{if(changing)return;changing=true;if(dub.Checked)korean.Checked=true;else if(captions.SelectedIndex==1)captions.SelectedIndex=0;changing=false;Describe();};
   captions.SelectedIndexChanged+=delegate{if(changing)return;changing=true;if(captions.SelectedIndex!=2)korean.Checked=true;if(captions.SelectedIndex==1)dub.Checked=true;changing=false;Describe();};wide.CheckedChanged+=delegate{Describe();};
   check.Click+=async delegate{await Run("--check");};apply.Click+=async delegate{await Run("--apply");};restore.Click+=async delegate{await Run("--restore");};recover.Click+=async delegate{await Run("--recover");};play.Click+=async delegate{await Run("--open");};FormClosing+=delegate(object s,FormClosingEventArgs e){if(busy)e.Cancel=true;};Describe();
  }
  string ProfileId(){return "k"+(korean.Checked?1:0)+"-w"+(wide.Checked?1:0)+"-d"+(dub.Checked?1:0)+"-"+(captions.SelectedIndex==1?"dub":captions.SelectedIndex==0?"original":"off");}
  void Describe(){description.Text=(korean.Checked?"한글 메뉴·글꼴":"게임 기본 언어")+" · "+(wide.Checked?"4:3/16:9 자동 · 최대 4K · AA 유지":"기존 4:3 해상도")+" · "+(dub.Checked?"한국어 음성":"영어 음성")+"\r\n"+(captions.SelectedIndex==2?"추가 무전·게임 내 컷신 자막은 끕니다. 게임의 영상 자막은 유지됩니다.":captions.SelectedIndex==1?"무전·영상 자막을 한국어 더빙 대사에 맞춥니다.":"기존 원문 번역 자막을 사용합니다.")+"\r\n"+(dub.Checked?"전체 더빙 설치는 약 14GB의 여유 공간을 권장합니다. API 키는 필요 없습니다.":"체크를 모두 해제하면 원본 구성으로 전환합니다.");}
  void Log(string s){if(InvokeRequired){BeginInvoke(new Action<string>(Log),s);return;}output.AppendText(s+Environment.NewLine);}
  async Task Run(string mode){if(busy)return;busy=true;string selected=root.Text,id=ProfileId();foreach(var c in new Control[]{root,browse,korean,wide,dub,captions,check,apply,restore,recover,play})c.Enabled=false;output.Clear();try{await Task.Run(delegate{var e=new PatchEngine(AppDomain.CurrentDomain.BaseDirectory,Log);if(mode=="--open")e.Open(selected);else e.Run(mode,selected,id);});}catch(Exception e){Log("중단 / Stopped: "+e.Message);MessageBox.Show(this,e.Message,"작업 중단 / Stopped",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{busy=false;foreach(var c in new Control[]{root,browse,korean,wide,dub,captions,check,apply,restore,recover,play})c.Enabled=true;}}
 }
 static class Program {
  [STAThread]public static int Main(string[] args){if(args.Length==0||args.Length==2&&args[0]=="--gui-root"){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new SetupForm(args.Length==2?args[1]:null));return 0;}try{Console.SetOut(new StreamWriter(Console.OpenStandardOutput(),new UTF8Encoding(false)){AutoFlush=true});Console.SetError(new StreamWriter(Console.OpenStandardError(),new UTF8Encoding(false)){AutoFlush=true});string mode=null,root=null,profile="k1-w1-d1-dub";for(int i=0;i<args.Length;i++){if(new[]{"--check","--apply","--restore","--recover","--open"}.Contains(args[i])&&mode==null)mode=args[i];else if(args[i]=="--root"&&root==null&&++i<args.Length)root=args[i];else if(args[i]=="--profile"&&++i<args.Length)profile=args[i];else throw new ArgumentException("Invalid arguments");}if(mode==null||root==null)throw new ArgumentException("Usage: CrimsonSkiesSetup.exe --check|--apply|--restore|--recover|--open --root CONTENT [--profile k1-w1-d1-dub]");var e=new PatchEngine(AppDomain.CurrentDomain.BaseDirectory,Console.WriteLine);if(mode=="--open")e.Open(root);else e.Run(mode,root,profile);return 0;}catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}
 }
}
